// MESA CLUB 7.0 · billar mejorado: predicción de bola objetivo y marcadores lisas/rayadas.
'use strict';
const fs=require('node:fs');const path=require('node:path');const crypto=require('node:crypto');const zlib=require('node:zlib');
const payload='';
const bytes=Buffer.from(payload,'base64');
if(crypto.createHash('sha256').update(bytes).digest('hex')!=='5d4ca1afb429e824b0ace7d7f9db14074e69be35d1dc2dcae5345adee02bfed0')throw Error('Integridad de MESA CLUB 7 inválida');
const contents=JSON.parse(zlib.brotliDecompressSync(bytes).toString('utf8'));
for(const [name,code] of Object.entries(contents)){
 if(!/^(server|chess|store|domino|pool|backup|migrate)\.js$|^public\/(index\.html|app\.js|styles\.css)$/.test(name))throw Error('Ruta de paquete inválida');
 const target=path.join(__dirname,name);fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,code);
}
console.log('MESA CLUB 7 preparado: guía de impacto, grupos y marcadores de billar.');
const {server}=require('./server');
const {init,getStorage,shutdown}=require('./store');
init().then(()=>server.listen(Number(process.env.PORT)||3000,'0.0.0.0',()=>console.log('MESA CLUB 7 online · almacenamiento: '+getStorage()))).catch(err=>{console.error('No se pudo conectar a la base de datos:',err.message);process.exitCode=1;shutdown().catch(()=>{});server.close();});
